// adapter.js — Browser polyfills for WeChat Mini Game
// Generated by MiniGameBackend

// === Shared Module object (must be before any subpackage loads) ===
// Both freetype.js and app.js reference this shared object via globalThis.Module.
// Without this, parallel subpackage loading causes a race: app.js may load
// before freetype.js and capture an empty {} instead of the FreeType Module.
if (!globalThis.Module) globalThis.Module = {};

// === console polyfill (must come before any code that reports errors) ===
if (typeof globalThis.console === 'undefined') {
    globalThis.console = { log: function(){}, error: function(){}, warn: function(){} };
}

// === window polyfill ===
// WeChat provides globalThis.window as a read-only getter on some platforms,
// but on real devices window may be completely undefined.
(function() {
    var win = (typeof window !== 'undefined') ? window : globalThis.window;
    if (!win) {
        win = globalThis;
        globalThis.window = globalThis;
    }
    if (typeof win.requestAnimationFrame === 'undefined') {
        win.requestAnimationFrame = function(cb) { return setTimeout(cb, 16); };
    }
    if (typeof win.cancelAnimationFrame === 'undefined') {
        win.cancelAnimationFrame = function(id) { clearTimeout(id); };
    }
    if (typeof win.devicePixelRatio === 'undefined') {
        win.devicePixelRatio = wx.getSystemInfoSync().pixelRatio;
    }
    if (typeof win.innerWidth === 'undefined') {
        win.innerWidth = wx.getSystemInfoSync().screenWidth;
    }
    if (typeof win.innerHeight === 'undefined') {
        win.innerHeight = wx.getSystemInfoSync().screenHeight;
    }
    if (typeof win.addEventListener === 'undefined') {
        win.addEventListener = function() {};
    }
    if (typeof win.removeEventListener === 'undefined') {
        win.removeEventListener = function() {};
    }
    if (typeof win.location === 'undefined') {
        win.location = { href: './' };
    }
    if (!('Gdx' in win)) {
        win.Gdx = undefined;
    }
})();

// === document polyfill ===
if (typeof document === 'undefined') {
    globalThis.document = {
        createElement: function(tag) {
            if (tag === 'canvas') return wx.createCanvas();
            return { style: {}, appendChild: function(){}, removeChild: function(){} };
        },
        getElementById: function() { return null; },
        addEventListener: function() {},
        removeEventListener: function() {},
        body: { appendChild: function(){}, removeChild: function(){} },
        head: { appendChild: function(){} },
        documentElement: { style: {} },
        querySelector: function() { return null; },
        querySelectorAll: function() { return []; }
    };
}

// === performance polyfill ===
if (typeof performance === 'undefined') {
    globalThis.performance = { now: Date.now };
}

// === Extracted Gdx WebAssembly ===
(function() {
    var standardWasm = typeof WebAssembly !== 'undefined' ? WebAssembly : null;
    var wxWasm = typeof WXWebAssembly !== 'undefined' ? WXWebAssembly : null;
    // Capture before patching; avoid recursion if the host aliases the two APIs.
    var instantiate = standardWasm && typeof standardWasm.instantiate === 'function'
        ? standardWasm.instantiate.bind(standardWasm) : null;
    var instantiatePath = wxWasm && wxWasm !== standardWasm && typeof wxWasm.instantiate === 'function'
        ? wxWasm.instantiate.bind(wxWasm) : null;
    if (!instantiatePath && instantiate) {
        // FreeType also calls the package-path API. Provide it in standard-only runtimes
        // without modifying the shared extension or attempting HTTP fetches of package files.
        instantiatePath = function(path, imports) {
            return new Promise(function(resolve, reject) {
                wx.getFileSystemManager().readFile({
                    filePath: path,
                    success: function(result) { resolve(result.data); },
                    fail: function(error) {
                        reject(new Error('Cannot read ' + path + ': ' + (error.errMsg || error)));
                    }
                });
            }).then(function(binary) { return instantiate(binary, imports); });
        };
        globalThis.WXWebAssembly = Object.create(standardWasm);
        globalThis.WXWebAssembly.instantiate = instantiatePath;
    }
    if (!standardWasm) globalThis.WebAssembly = {};
    WebAssembly.instantiate = function(source, imports) {
        var bytes = source instanceof ArrayBuffer ? new Uint8Array(source)
            : ArrayBuffer.isView(source) ? new Uint8Array(source.buffer, source.byteOffset, source.byteLength) : null;
        // The builder replaces ONLY Gdx's embedded binary with one zero byte. Leave other
        // modules/binaries alone; intercepting every byte buffer would load Gdx for them too.
        if (!bytes || bytes.length !== 1 || bytes[0] !== 0) {
            return instantiate ? instantiate(source, imports) : Promise.reject(new Error('No standard WASM support'));
        }
        var path = 'subpackages/engine/gdx.wasm';
        return instantiatePath ? instantiatePath(path, imports)
            : Promise.reject(new Error('No WASM support for ' + path));
    };
})();

// === atob polyfill ===
if (typeof atob === 'undefined') {
    var atob = function(base64) {
        var chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
        var lookup = {};
        for (var i = 0; i < chars.length; i++) lookup[chars[i]] = i;
        var output = '';
        var buffer = 0, bufferLen = 0;
        for (var j = 0; j < base64.length; j++) {
            var ch = base64.charAt(j);
            if (ch === '=') break;
            buffer = (buffer << 6) | lookup[ch];
            bufferLen += 6;
            if (bufferLen >= 8) {
                bufferLen -= 8;
                output += String.fromCharCode((buffer >> bufferLen) & 0xFF);
            }
        }
        return output;
    };
    globalThis.atob = atob;
}

exports.setup = function(canvas) {
    globalThis.canvas = canvas;
};

// === XMLHttpRequest polyfill (wraps wx.request) ===
if (typeof XMLHttpRequest === 'undefined') {
    var XHR = function() {
        this.readyState = 0;
        this.status = 0;
        this.statusText = '';
        this.responseText = '';
        this.response = '';
        this.responseType = '';
        this.responseHeaders = {};
        this._method = '';
        this._url = '';
        this._headers = {};
        this._async = true;
        this.onreadystatechange = null;
        this.onerror = null;
        this.onload = null;
    };
    XHR.UNSENT = 0;
    XHR.OPENED = 1;
    XHR.HEADERS_RECEIVED = 2;
    XHR.LOADING = 3;
    XHR.DONE = 4;
    XHR.prototype.open = function(method, url, async) {
        this._method = method;
        this._url = url;
        this._async = (async !== false);
        this.readyState = XHR.OPENED;
    };
    XHR.prototype.setRequestHeader = function(name, value) {
        this._headers[name] = value;
    };
    XHR.prototype.send = function(data) {
        var self = this;
        var opts = {
            url: self._url,
            method: self._method,
            header: self._headers,
            data: (data !== undefined && data !== null) ? data : undefined,
            dataType: 'text',
            success: function(res) {
                self.status = res.statusCode;
                self.statusText = '';
                self.responseText = (typeof res.data === 'string') ? res.data : JSON.stringify(res.data);
                self.response = self.responseText;
                self.responseHeaders = res.header || {};
                self.readyState = XHR.HEADERS_RECEIVED;
                if (self.onreadystatechange) self.onreadystatechange();
                self.readyState = XHR.LOADING;
                if (self.onreadystatechange) self.onreadystatechange();
                self.readyState = XHR.DONE;
                if (self.onreadystatechange) self.onreadystatechange();
                if (self.onload) self.onload();
            },
            fail: function(err) {
                self.status = 0;
                self.readyState = XHR.DONE;
                if (self.onreadystatechange) self.onreadystatechange();
                if (self.onerror) self.onerror(err);
            }
        };
        wx.request(opts);
    };
    XHR.prototype.abort = function() {};
    XHR.prototype.getAllResponseHeaders = function() {
        var result = '';
        for (var k in this.responseHeaders) {
            if (this.responseHeaders.hasOwnProperty(k)) {
                result += k + ': ' + this.responseHeaders[k] + '\r\n';
            }
        }
        return result;
    };
    XHR.prototype.getResponseHeader = function(name) {
        return this.responseHeaders[name] || null;
    };
    XHR.prototype.overrideMimeType = function() {};
    globalThis.XMLHttpRequest = XHR;
}
